# GET https://solid.example.org/pitas-g3/profile/card
@prefix foaf:  <http://xmlns.com/foaf/0.1/> .
@prefix solid: <http://www.w3.org/ns/solid/terms#> .
@prefix pim:   <http://www.w3.org/ns/pim/space#> .
@prefix ldp:   <http://www.w3.org/ns/ldp#> .

<#me> a foaf:Agent ;
  foaf:name "PITAS auction house of group 3" ;
  solid:oidcIssuer <https://solid.example.org/> ;
  pim:storage <../> ;
  solid:publicTypeIndex <../settings/publicTypeIndex.ttl> ;
  ldp:inbox <../inbox/> .

PATCH /pitas-g3/pitas/auctions/a-001.ttl HTTP/1.1
Content-Type: text/n3
If-Match: "1f3a-9c"

@prefix solid: <http://www.w3.org/ns/solid/terms#> .
@prefix pitas: <https://pitas.example.org/ns#> .
_:close a solid:InsertDeletePatch ;
  solid:where   { <#it> pitas:status pitas:Open . } ;
  solid:deletes { <#it> pitas:status pitas:Open . } ;
  solid:inserts { <#it> pitas:status pitas:Closed . } .

# /pitas-g3/pitas/auctions/a-001/bids/.acl
@prefix acl:  <http://www.w3.org/ns/auth/acl#> .
@prefix foaf: <http://xmlns.com/foaf/0.1/> .

<#submit> a acl:Authorization ;
    acl:agentClass foaf:Agent ;
    acl:accessTo   <./> ;
    acl:default    <./> ;
    acl:mode       acl:Append .

<#house> a acl:Authorization ;
    acl:agent    </pitas-g3/profile/card#me> ;
    acl:accessTo <./> ;
    acl:default  <./> ;
    acl:mode     acl:Read, acl:Write, acl:Control .

@prefix sh:     <http://www.w3.org/ns/shacl#> .
@prefix schema: <https://schema.org/> .
@prefix prov:   <http://www.w3.org/ns/prov#> .
@prefix xsd:    <http://www.w3.org/2001/XMLSchema#> .
@prefix pitas:  <https://pitas.example.org/ns#> .

pitas:BidShape a sh:NodeShape ;
  sh:targetClass pitas:Bid ;
  sh:property [ sh:path pitas:forAuction ;
                sh:nodeKind sh:IRI ; sh:minCount 1 ] ;
  sh:property [ sh:path schema:price ;
                sh:datatype xsd:decimal ; sh:maxCount 1 ] ;
  sh:property [ sh:path prov:wasAttributedTo ;
                sh:nodeKind sh:IRI ; sh:minCount 1 ] .
